def rotate_left(values, steps):
    if not values:
        return []
    steps %= len(values)
    return values[steps:] + values[:steps]

def unique_in_order(values):
    seen = set()
    result = []
    for value in values:
        if value not in seen:
            seen.add(value)
            result.append(value)
    return result

def merge_counts(first, second):
    result = dict(first)
    for key, value in second.items():
        result[key] = result.get(key, 0) + value
    return result

